const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const S = { state: null, ui: {}, parties: [], items: [], pos: [] };

async function api(p, o = {}) {
  const r = await fetch('/api/' + p, { method: o.method || 'GET', headers: o.body ? { 'content-type': 'application/json' } : {}, body: o.body ? JSON.stringify(o.body) : undefined });
  const t = await r.text(); let j; try { j = JSON.parse(t); } catch { j = { error: t }; }
  if (!r.ok) throw new Error(j.error || 'خطأ');
  return j;
}
const msg = (t, ok) => { const m = $('#msg'); if (m) { m.className = 'msg' + (ok ? ' ok' : ''); m.textContent = t; m.hidden = !t; } };
const newSaleRequestId=()=>{if(globalThis.crypto?.randomUUID)return globalThis.crypto.randomUUID();const bytes=new Uint8Array(16);globalThis.crypto.getRandomValues(bytes);bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const h=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20);};
const localScope = () => S.state?.installation_id && S.state?.user ? S.state.installation_id+':'+S.state.user.id : null;
const guard = fn => async (...a) => { try { await fn(...a); } catch (e) { msg(e.message); } };

const nf = () => new Intl.NumberFormat('ar-SA-u-nu-' + (S.ui.digits === 'arab' ? 'arab' : 'latn'), { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const money = v => nf().format(Number(v));
const fdate = d => d ? new Date(d + 'T00:00:00').toLocaleDateString('ar-SA-u-nu-' + (S.ui.digits === 'arab' ? 'arab' : 'latn') + '-ca-' + (S.ui.calendar === 'hijri' ? 'islamic-umalqura' : 'gregory')) : '';

function applyUI() {
  const u = S.ui, d = document.documentElement, dark = u.theme === 'dark' || (u.theme === 'auto' && matchMedia('(prefers-color-scheme:dark)').matches);
  d.dataset.theme = dark ? 'dark' : 'light'; d.dataset.density = u.density; d.dataset.sidebar = u.sidebar;
  d.style.setProperty('--accent', u.accent); d.style.setProperty('--fs', u.fontScale); d.style.setProperty('--r', u.radius + 'px');
  d.style.setProperty('--font', { system: 'Tahoma,"Segoe UI",Arial,sans-serif', serif: '"Traditional Arabic","Times New Roman",serif', mono: 'Consolas,monospace' }[u.font] || 'Tahoma,sans-serif');
}

const ICONS = { dashboard:'▦', invoices:'▤', new:'＋', parties:'♙', items:'◇', reports:'▥', settings:'⚙', pos:'▣' };
const NAV = [['dashboard', 'نظرة عامة'], ['invoices', 'المبيعات والفواتير'], ['new', 'فاتورة جديدة'], ['pos', 'نقطة البيع'], ['parties', 'العملاء'], ['items', 'الأصناف والخدمات'], ['reports', 'التقارير المالية'], ['compliance','الفوترة والهيئة'], ['print', 'إعدادات الطباعة'], ['settings', 'الإعدادات']];
const WORKSPACES = { trade: { name:'التجاري والخدمات', subtitle:'أعمالك اليومية، في مكان واحد', item:'صنف أو خدمة' }, events: { name:'الحفلات والمناسبات', subtitle:'فواتير تجهيزاتك وخدمات مناسباتك', item:'تجهيز أو خدمة' }, engineering: { name:'الهندسي والمقاولات', subtitle:'فواتير الأعمال والخدمات الهندسية', item:'بند أعمال أو خدمة' } };
let workspace = localStorage.getItem('smartz.workspace') || 'trade';
if (!WORKSPACES[workspace]) workspace = 'trade';
function shell(body) {
  const cur = location.hash.slice(1) || (S.state.user.role === 'staff' ? 'pos' : 'dashboard'), w = WORKSPACES[workspace];
  $('#app').innerHTML = '<div class="shell"><nav aria-label="القائمة الرئيسية"><a class="brand" href="#pos"><img class="brand-logo" src="/assets/almuhtariz-logo.png" alt="شعار المحترز"><strong dir="rtl">المحترز للمحاسبة<small>وإدارة الأعمال</small></strong></a><div class="workspace-label">مساحة العمل</div><select id="workspace" aria-label="النشاط">' + Object.entries(WORKSPACES).map(([k,v])=>'<option value="'+k+'" '+(k===workspace?'selected':'')+'>'+v.name+'</option>').join('') + '</select><div class="nav-label">إدارة الأعمال</div>'+NAV.filter(([k]) => S.state.user.role==='staff' ? k==='pos' : (!['settings','print','compliance'].includes(k) || S.state.user.role === 'owner')).map(([k,t])=>'<a class="'+(cur===k?'on':'')+'" href="#'+k+'" '+(cur===k?'aria-current="page"':'')+'><span class="nav-icon" aria-hidden="true">'+ICONS[k]+'</span>'+t+'</a>').join('')+'<div class="nav-bottom"><div class="profile"><span class="avatar">'+esc(S.state.user.username.slice(0,1))+'</span><div><b>'+esc(S.state.user.username)+'</b><small>'+({owner:'مالك المنشأة',accountant:'محاسب',staff:'موظف'}[S.state.user.role]||'')+'</small></div><button id="out" aria-label="تسجيل الخروج">↪</button></div></div></nav><main><header class="topbar"><div><span class="eyebrow">'+esc(w.name)+'</span><span class="top-divider">/</span><span>'+esc(NAV.find(([k])=>k===cur)?.[1]||'نظرة عامة')+'</span></div><div class="top-actions"><span class="today">'+fdate(S.state.today)+'</span><a class="button p" href="#new">＋ فاتورة جديدة</a></div></header><div class="content"><div id="msg" class="msg" role="status" hidden></div><div class="development-notice">نسخة تطوير · المستندات تجريبية وغير صالحة للاستخدام الضريبي</div>'+body+'</div><footer class="app-footer"><span dir="rtl">المحترز للمحاسبة</span><span>تفاصيل أقل. وضوح أكثر.</span></footer></main></div>';
  if(S.state.user.role==='staff'){$('#workspace').hidden=true;$('.workspace-label').hidden=true;$('.top-actions .button').href='#pos';$('.top-actions .button').textContent='نقطة البيع';}
  $('#workspace').onchange = e => { workspace=e.target.value;localStorage.setItem('smartz.workspace',workspace); route(); };
  $('#out').onclick = guard(async () => { await api('logout', { method: 'POST', body: {} }); await globalThis.AlmuhtarizStore?.clearScope(localScope()); location.reload(); });
}

