function openingScreen() {
 clearTimeout(S.openingTimer);
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(reduced){S.introComplete=true;sessionStorage.almuhtarizOpened='1';return route();}
 $('#app').innerHTML='<section class="brand-opening" aria-label="افتتاح المحترز للمحاسبة"><div class="opening-grid" aria-hidden="true"></div><div class="opening-aura" aria-hidden="true"></div><button id="skip-opening" type="button">تجاوز الافتتاحية ←</button><div class="opening-identity"><div class="opening-emblem"><span class="opening-ring ring-first"></span><span class="opening-ring ring-second"></span><span class="opening-ring ring-third"></span><img src="/assets/almuhtariz-logo.png" alt="شعار المحترز"></div><div class="opening-line"></div><h1>المحترز للمحاسبة</h1><p>وإدارة الأعمال</p><span class="opening-signature">كل التفاصيل. في مكانها.</span></div></section>';
 let finished=false;const finish=()=>{if(finished)return;finished=true;clearTimeout(S.openingTimer);S.introComplete=true;sessionStorage.almuhtarizOpened='1';route();};
 $('#skip-opening').onclick=finish;S.openingTimer=setTimeout(finish,1800);
}

function activityScreen() {
 const cards={trade:{title:'التجاري',description:'مبيعاتك وعملاؤك وأصنافك، بخطوات واضحة.',icon:"<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"><path d=\"M4 9h16v11H4zM3 9l2-5h14l2 5M9 20v-7h6v7M3 9c0 3 4 3 4 0 0 3 5 3 5 0 0 3 5 3 5 0 0 3 4 3 4 0\"/></svg>"},events:{title:'الحفلات',description:'فواتير تجهيز الحفلات وخدمات المناسبات.',icon:"<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"><path d=\"M5 4l15 15M9 4l2 4M16 3l-1 4M21 8l-4 2M4 12L2 22l10-2zM15 14l5-2M13 8l3 3\"/></svg>"},engineering:{title:'الهندسي',description:'فواتير بنود الأعمال والخدمات الهندسية.',icon:"<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"><path d=\"M3 21h18M5 21V8h8v13M13 21V3h6v18M8 11h2M8 15h2M8 18h2M15 7h2M15 11h2M15 15h2\"/></svg>"}};
 const savedMotion=localStorage.getItem('almuhtariz.motion');
 const motion=savedMotion===null?!matchMedia('(prefers-reduced-motion: reduce)').matches:savedMotion==='on';
 const cube=(name)=>'<div class="entry-cube '+name+'"><div class="entry-cube-spin">'+['front','back','right','left','top','bottom'].map(face=>'<i class="cube-face cube-'+face+'"></i>').join('')+'</div></div>';
 $('#app').innerHTML='<section class="activity-start saas-entry" data-motion="'+(motion?'on':'off')+'"><div class="entry-ambient" aria-hidden="true"><div class="entry-glow glow-one"></div><div class="entry-glow glow-two"></div><div class="entry-grid"></div><div class="entry-orbit orbit-one"></div><div class="entry-orbit orbit-two"></div></div><div class="entry-shell"><header class="entry-header"><a class="entry-brand" href="#" aria-label="المحترز للمحاسبة"><img src="/assets/almuhtariz-logo.png" alt="شعار المحترز"><span><b>المحترز للمحاسبة</b><small>وإدارة الأعمال</small></span></a><div class="entry-header-tools"><span class="entry-local"><i></i> داخل شبكة الفرع</span><button id="entry-motion" type="button" aria-pressed="'+motion+'">'+(motion?'إيقاف الحركة ⏸':'تشغيل الحركة ▶')+'</button></div></header><div class="entry-hero"><div class="entry-copy"><div class="entry-eyebrow"><span></span> مساحة لكل طموح</div><h1>المحترز.<br><em>للمحاسبة وإدارة الأعمال.</em></h1><p>حساباتك وفواتيرك وفريقك، في مساحة واحدة.<br>اختر نشاطك وابدأ يومك بوضوح.</p><div class="entry-feature-line"><span>واجهة عربية</span><i>·</i><span>محاسب ونقطة بيع</span><i>·</i><span>تشغيل محلي</span></div></div><div class="entry-visual" aria-hidden="true"><div class="entry-visual-halo"></div><div class="entry-scene"><div class="brand-core"><div class="brand-core-ring ring-a"></div><div class="brand-core-ring ring-b"></div><div class="brand-core-disc"><img src="/assets/almuhtariz-logo.png" alt=""></div><span class="brand-core-spark"></span></div><div class="entry-chart-panel"><div class="scene-panel-heading"><i></i><i></i><i></i><span></span></div><div class="scene-chart"><b style="--bar:.28"></b><b style="--bar:.48"></b><b style="--bar:.39"></b><b style="--bar:.65"></b><b style="--bar:.57"></b><b style="--bar:.83"></b><b style="--bar:1"></b></div><div class="scene-panel-lines"><span></span><span></span></div></div><div class="entry-receipt-panel"><span class="scene-check">✓</span><div><i></i><i></i><i></i></div><span class="scene-receipt-dot"></span></div><div class="entry-stack"><i></i><i></i><i></i></div>'+cube('cube-large')+cube('cube-small')+'<div class="entry-motion-orbit"><i></i></div><div class="entry-scene-ring"></div></div></div></div><div class="entry-choose-label"><span>اختر مساحة عملك</span><span class="entry-choice-line"></span><small>يمكنك تغيير النشاط لاحقًا</small></div><div class="activity-options">'+Object.entries(cards).map(([key,card],i)=>'<button type="button" class="activity-option '+(S.state.activity===key?'is-default':'')+'" data-activity="'+key+'"><span class="entry-card-top"><span class="activity-symbol">'+card.icon+'</span><span class="entry-card-number">0'+(i+1)+'</span></span><span class="entry-card-body"><span class="activity-title">'+card.title+'</span><span class="activity-description">'+card.description+'</span></span><span class="activity-enter">دخول مساحة العمل <i>↗</i></span>'+(S.state.activity===key?'<span class="entry-default">نشاطك الافتراضي</span>':'')+'</button>').join('')+'</div><footer class="entry-footer"><span>المحترز للمحاسبة <i>© 2026</i></span><span>الفواتير والعملاء مشتركون بين مساحات العمل</span><span class="entry-footer-sign">صُمّم لوضوح أعمالك <i>✦</i></span></footer></div></section>';
 $$('[data-activity]').forEach(button=>button.onclick=()=>{workspace=button.dataset.activity;localStorage.setItem('smartz.workspace',workspace);S.activitySelected=true;route();});
 $('#entry-motion').onclick=()=>{const screen=$('.saas-entry'),button=$('#entry-motion'),enabled=screen.dataset.motion!=='on';screen.dataset.motion=enabled?'on':'off';localStorage.setItem('almuhtariz.motion',enabled?'on':'off');button.setAttribute('aria-pressed',String(enabled));button.textContent=enabled?'إيقاف الحركة ⏸':'تشغيل الحركة ▶';};
}

function authScreen() {
 const setup=S.state.setup_needed;
 const motion=localStorage.getItem('almuhtariz.motion')!=='off'&&!matchMedia('(prefers-reduced-motion: reduce)').matches;
 $('#app').innerHTML='<section class="auth-entry" data-motion="'+(motion?'on':'off')+'"><div class="auth-ambient" aria-hidden="true"></div><div class="auth-layout"><header class="auth-header"><a href="#" id="auth-home" class="entry-brand"><img src="/assets/almuhtariz-logo.png" alt="شعار المحترز"><span><b>المحترز للمحاسبة</b><small>وإدارة الأعمال</small></span></a><button id="back-activities" type="button">تغيير النشاط ←</button></header><div class="auth-story"><span class="auth-eyebrow">'+esc(WORKSPACES[workspace].name)+'</span><h1>خطوتك القادمة،<br><em>أكثر وضوحًا.</em></h1><p>حساباتك وعملاؤك وفواتيرك.<br>كل التفاصيل في مساحة عملك.</p><div class="auth-emblem" aria-hidden="true"><span></span><img src="/assets/almuhtariz-logo.png" alt=""></div><div class="auth-local"><i></i> متصل بخادم الفرع المحلي</div></div><section class="auth-panel"><div class="auth-panel-heading"><span class="eyebrow">'+(setup?'لنبدأ معًا':'أهلًا بعودتك')+'</span><h2>'+(setup?'أنشئ مساحة أعمالك':'سجّل دخولك')+'</h2><p>'+(setup?'بيانات بسيطة لتجهيز منشأتك وحساب المالك.':'أدخل بيانات حسابك للمتابعة إلى مساحة عملك.')+'</p></div><div id="msg" class="msg" role="status" hidden></div><form id="login-form">'+(setup?'<label for="co">اسم المنشأة<input id="co" name="company" autocomplete="organization" placeholder="اسم منشأتك" required></label>':'')+'<label for="u">اسم المستخدم<input id="u" name="username" autocomplete="username" placeholder="أدخل اسم المستخدم" required></label><label for="p">كلمة المرور</label><div class="password-field"><input id="p" name="password" type="password" autocomplete="'+(setup?'new-password':'current-password')+'" placeholder="'+(setup?'8 أحرف على الأقل':'أدخل كلمة المرور')+'" '+(setup?'minlength="8"':'')+' required><button id="toggle-password" type="button" aria-pressed="false" aria-label="إظهار كلمة المرور">إظهار</button></div><button class="auth-submit" type="submit" id="go">'+(setup?'إنشاء وبدء العمل':'دخول مساحة العمل')+' <span>←</span></button><p class="auth-form-note">'+(setup?'سيكون هذا الحساب مالك المنشأة. يمكنك إضافة فريقك لاحقًا.':'استخدم الحساب الذي أنشأه مالك المنشأة لك.')+'</p></form><div class="auth-panel-footer"><span>'+esc(WORKSPACES[workspace].name)+'</span><span>المحترز للمحاسبة</span></div></section><footer class="auth-footer">أعمال متعددة. هوية واحدة.</footer></div></section>';
 const back=e=>{e.preventDefault();S.activitySelected=false;activityScreen();};$('#back-activities').onclick=back;$('#auth-home').onclick=back;
 $('#toggle-password').onclick=()=>{const input=$('#p'),button=$('#toggle-password'),show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'إخفاء':'إظهار';button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',show?'إخفاء كلمة المرور':'إظهار كلمة المرور');};
 $('#login-form').onsubmit=guard(async e=>{e.preventDefault();const button=$('#go'),label=button.innerHTML;button.disabled=true;button.textContent='جارٍ تجهيز مساحة عملك…';try{const body={username:$('#u').value.trim(),password:$('#p').value};if(setup)await api('setup',{method:'POST',body:{...body,company_name:$('#co').value.trim(),activity:workspace}});await api('login',{method:'POST',body});sessionStorage.skipActivityOnce='1';location.reload();}finally{button.disabled=false;button.innerHTML=label;}});
}

