// ---------- إشعار دائن ----------
async function debitDialog(id){const d=$('#dlg');d.innerHTML='<h3>إشعار مدين · زيادة على الفاتورة الأصلية</h3><p class="hint">لخدمة إضافية خاضعة للنسبة الأساسية 15%. التصحيح بالنقص يتم بإشعار دائن.</p><label>وصف الخدمة<input id="debit-description"></label><label>القيمة قبل الضريبة<input id="debit-value" type="number" min="0.01" step="0.01"></label><label>السبب<input id="debit-reason"></label><div id="debit-error" class="msg" hidden></div><div class="row"><button class="p" id="debit-confirm">إصدار تجريبي</button><button id="debit-cancel">إلغاء</button></div>';d.showModal();$('#debit-cancel').onclick=()=>d.close();$('#debit-confirm').onclick=async()=>{try{const response=await api('invoices/'+id+'/debit-note',{method:'POST',body:{reason:$('#debit-reason').value,lines:[{description:$('#debit-description').value,qty:1,unit_price:$('#debit-value').value,vat_rate:15}]}});d.close();window.open('/api/invoices/'+response.id+'/html','_blank');pages.invoices();}catch(e){$('#debit-error').textContent=e.message;$('#debit-error').hidden=false;}};}

async function creditDialog(id) {
  const inv = await api('invoices/' + id), d = $('#dlg');
  d.innerHTML = `<h3>إشعار دائن للفاتورة ${esc(inv.number)}</h3><table><thead><tr><th>البند</th><th>المتبقي</th><th>الكمية المرجعة</th></tr></thead><tbody>
  ${inv.lines.map(l => `<tr><td>${esc(l.description)}</td><td>${l.remaining}</td><td><input type="number" min="0" max="${l.remaining}" step="any" value="0" data-l="${l.line_no}" style="width:90px"></td></tr>`).join('')}</tbody></table>
  <label>سبب الإشعار<input id="rs"></label><div id="dm" class="msg" hidden></div><div class="row"><button class="p" id="ok">إصدار</button><button id="x">إلغاء</button></div>`;
  d.showModal(); $('#x', d).onclick = () => d.close();
  $('#ok', d).onclick = async () => { try { const lines = $$('[data-l]', d).filter(i => +i.value > 0).map(i => ({ line_no: +i.dataset.l, qty: +i.value }));
    if (!lines.length) throw new Error('حدد كمية واحدة على الأقل للإرجاع');
    const r = await api(`invoices/${id}/credit-note`, { method: 'POST', body: { lines, reason: $('#rs', d).value } }); d.close(); window.open(`/api/invoices/${r.id}/html`, '_blank'); pages.invoices();
  } catch (e) { const m = $('#dm', d); m.textContent = e.message; m.hidden = false; } };
}


async function reviewInvoice(total, count) {
  const d = $('#dlg');
  d.innerHTML = '<span class="eyebrow">الخطوة الأخيرة</span><h3>راجع الفاتورة قبل إصدارها</h3><p class="hint">'+count+' بنود. بعد الإصدار تُحفظ الفاتورة ويصبح التصحيح بإشعار دائن.</p><div class="review-total">'+esc(total)+'</div><div class="row"><button class="p" id="confirm-issue">تأكيد وإصدار الفاتورة</button><button id="back-to-edit">العودة للتعديل</button></div>';
  return new Promise(resolve => { let done=false; const finish=v=>{if(done)return;done=true;d.close();resolve(v);}; $('#confirm-issue',d).onclick=()=>finish(true); $('#back-to-edit',d).onclick=()=>finish(false);d.oncancel=()=>finish(false); d.onclose=()=>{if(!done){done=true;resolve(false);}}; d.showModal(); });
}

// ---------- التشغيل ----------
async function route() { if(S.state?.user?.role==='staff'){workspace='trade';S.activitySelected=true;if(location.hash!=='#pos')history.replaceState(null,'','#pos');}
 if (!S.introComplete && sessionStorage.almuhtarizOpened!=='1') return openingScreen(); if (!S.activitySelected) return activityScreen(); if (!S.state.user) return authScreen(); const k = (location.hash.slice(1) || (S.state.user.role === 'staff' ? 'pos' : 'dashboard')); try { await (pages[k] || pages.dashboard)(); } catch (e) { shell(`<div class="msg">${esc(e.message)}</div>`); } }
(async () => {
  S.state = await api('state');
  if (S.state.activity && WORKSPACES[S.state.activity]) workspace=S.state.activity;
  if (sessionStorage.skipActivityOnce==='1') { S.activitySelected=true; delete sessionStorage.skipActivityOnce; }
  if (S.state.user) { S.ui = await api('preferences/ui'); applyUI(); }
  addEventListener('hashchange', route); route();
})().catch(e => {
  $('#app').innerHTML = `<main class="auth"><h1>المحترز للمحاسبة وإدارة الأعمال</h1><div class="msg" role="alert">${esc(e.message)}</div><button id="retry-start">إعادة المحاولة</button></main>`;
  $('#retry-start').onclick = () => location.reload();
});
